Lemma geo_1RB1LD_0LC0RB_1LD1LA_1LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_0LC0RB_1LD1LA_1LA1RC) = lift (Cc (Pos.succ p)).
