(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_0LC0RB_1LD1LC_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_00_01_0 q0 ++ [S0;S1;S0]) [] j A0_1RB1LD_0LC0RB_1LD1LC_1LA0RC.
Proof.
  intros p j q0 E. destruct (Alph_00_01_0.cview_some_Alph_00_01_0 p j q0 E) as (H1 & _).
  unfold Cc_1RB1LD_0LC0RB_1LD1LC_1LA0RC, cden, A0_1RB1LD_0LC0RB_1LD1LC_1LA0RC; cbn [c_st c_l c_h c_r].
