Lemma gsi_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_000_010_01 q0 ++ [S0]) [] j A0_1RB1LD_0LC0RB_1LD1RC_0LA1LA.
