Lemma lapi_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
