Lemma lbl_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB1LD_0LC0RB_1LD1RC_0LA1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_000_010_01.cview_none_Alph_000_010_01 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB1LD_0LC0RB_1LD1RC_0LA1LA
             = (StD, (rep [S0;S0;S0] (S j) ++ [S0;S1], S0, [S1;S0;S1]))).
  { unfold cden, B1_1RB1LD_0LC0RB_1LD1RC_0LA1LA, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S0;S0;S0] (S j) ++ [S0;S1]) ++ [S0], S0, [S1;S0;S1]))).
  { unfold Cc_1RB1LD_0LC0RB_1LD1RC_0LA1LA. rewrite H2.
