(** ** The lap *)

Lemma lap_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_0LC0RB_1LD1RC_0LA1LA p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC0RB_1LD1RC_0LA1LA B0_1RB1LD_0LC0RB_1LD1RC_0LA1LA B1_1RB1LD_0LC0RB_1LD1RC_0LA1LA 10 22 p j' [] []).
    + exact run_ovf_1RB1LD_0LC0RB_1LD1RC_0LA1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LC0RB_1LD1RC_0LA1LA p j' E).
    + exact (geo_1RB1LD_0LC0RB_1LD1RC_0LA1LA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LD_0LC0RB_1LD1RC_0LA1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 24.
  assert (H : match csteps tm 24 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 24 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_0LC0RB_1LD1RC_0LA1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LC0RB_1LD1RC_0LA1LA = Some t ->
