(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LD_0LC0RB_1LD1RD_1LA0RC : sconf := mkC StC (mkS [] [S0;S1] 1 0 [S0;S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_1RB1LD_0LC0RB_1LD1RD_1LA0RC : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 1; SWinR 3; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2; SWinR 2; SFoldL 1].

Lemma run_exit_1RB1LD_0LC0RB_1LD1RD_1LA0RC : srun tm true true che_1RB1LD_0LC0RB_1LD1RD_1LA0RC BE0_1RB1LD_0LC0RB_1LD1RD_1LA0RC = Some (B1_1RB1LD_0LC0RB_1LD1RD_1LA0RC, 8, 19).
