Lemma lapin_1RB1LD_0LC0RB_1LD1RD_1LA0RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 6), (cden (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i AI1_1RB1LD_0LC0RB_1LD1RD_1LA0RC).
  split; [lia|]. split; [| exact (gen_1RB1LD_0LC0RB_1LD1RD_1LA0RC v i q0 E)].
