  exact (srun_sound tm false true chn_1RB1LD_0LC0RB_1LD1RD_1LA0RC AI0_1RB1LD_0LC0RB_1LD1RD_1LA0RC AI1_1RB1LD_0LC0RB_1LD1RD_1LA0RC 4 6
           run_inner_1RB1LD_0LC0RB_1LD1RD_1LA0RC (Ap_Alph_00_01_0 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
