(** ** The lap *)

Lemma lap_1RB1LD_0LC1LD_1LB1RC_0RC0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
