  - destruct (lapi_1RB1LD_0LC1LD_1LB1RC_0RC0LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_0LC1LD_1LB1RC_0RC0LA B0_1RB1LD_0LC1LD_1LB1RC_0RC0LA B1_1RB1LD_0LC1LD_1LB1RC_0RC0LA 4 15 p j' [] []).
    + exact run_ovf_1RB1LD_0LC1LD_1LB1RC_0RC0LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_0LC1LD_1LB1RC_0RC0LA p j' E).
    + exact (geo_1RB1LD_0LC1LD_1LB1RC_0RC0LA p j' E).
    + lia.
Qed.

