    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_0LC1RA_1LA0LD_1LC0RB [] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_0LC1RA_1LA0LD_1LC0RB [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SWinL 3] (StB, S1) ltac:(vm_compute; reflexivity)
