Lemma gsi_1RB1LD_0LC1RC_1LD0RB_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_1RB1LD_0LC1RC_1LD0RB_1RB1LA.
