Lemma fireo_1RB1LD_0LC1RC_1LD0RB_1RB1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_0LC1RC_1LD0RB_1RB1LA = Some t ->
  forall p j, cview p = (S j, None) ->
