    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_0RC1RB_0LD1RC_1LA0RC (StA, S0)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_0RC1RB_0LD1RC_1LA0RC [SCycL 2 0; SWin 1; SWinL 2] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
