      with (l := [SRotL 1; SWin 5]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1LB0RC_1LA1RC_0RD0LA
