  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB1LD_1LB1RC_0LD0RB_1RB1LA
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem nqhtr_1RB1LD_1LB1RC_0LD0RB_1RB1LA : NeverQuasiHaltsTr tm_1RB1LD_1LB1RC_0LD0RB_1RB1LA.
