(** ** The lap *)

Lemma lap_1RB1LD_1LC0RB_0RA0LC_0LD0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
