  - destruct (lapi_1RB1LD_1LC0RB_0RA0LC_0LD0LC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1LC0RB_0RA0LC_0LD0LC B0_1RB1LD_1LC0RB_0RA0LC_0LD0LC B1_1RB1LD_1LC0RB_0RA0LC_0LD0LC 2 14 p j' [] []).
    + exact run_ovf_1RB1LD_1LC0RB_0RA0LC_0LD0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1LC0RB_0RA0LC_0LD0LC p j' E).
    + exact (geo_1RB1LD_1LC0RB_0RA0LC_0LD0LC p j' E).
    + lia.
Qed.

