  srun_instr tm true true l B0_1RB1LD_1LC0RB_0RA0LC_0LD0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1LC0RB_0RA0LC_0LD0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LC0RB_0RA0LC_0LD0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LC0RB_0RA0LC_0LD0LC : forall t, ~ In t pins_1RB1LD_1LC0RB_0RA0LC_0LD0LC ->
