(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_1LC0RB_0RA1RB_0LD0LC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB1LD_1LC0RB_0RA1RB_0LD0LC.
