    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LC1LA_0LA1RC_1LB0RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_1RB1LD_1LC1LA_0LA1RC_1LB0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LD_1LC1LA_0LA1RC_1LB0RC = Some t ->
