                /\ lift c = lift (Cin (pow2 j))).
  { exists (6 * j + 17), (cden [] [] j BB1_1RB1LD_1LC1LA_0LA1RC_1LB0RC).
    split; [lia|]. split; [| exact (gbo_1RB1LD_1LC1LA_0LA1RC_1LB0RC j)].
