             run_boot_1RB1LD_1LC1LA_0LA1RC_1LB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_1RB1LD_1LC1LA_0LA1RC_1LB0RC p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (6 * j + 4), (cden [] [] j BM1_1RB1LD_1LC1LA_0LA1RC_1LB0RC).
    split; [| exact (gbo2_1RB1LD_1LC1LA_0LA1RC_1LB0RC j)].
    rewrite (gxi_1RB1LD_1LC1LA_0LA1RC_1LB0RC j).
    exact (srun_sound tm true true chm_1RB1LD_1LC1LA_0LA1RC_1LB0RC BM0_1RB1LD_1LC1LA_0LA1RC_1LB0RC BM1_1RB1LD_1LC1LA_0LA1RC_1LB0RC 6 4
             run_shift_1RB1LD_1LC1LA_0LA1RC_1LB0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
