    written. *)
Lemma lapo_1RB1LD_1LC1LD_0RD0LC_1RA1RD : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LD_1LC1LD_0RD0LC_1RA1RD p (pow2 j)).
  - exists (8 * j + 6), (cden [] [] j BB1_1RB1LD_1LC1LD_0RD0LC_1RA1RD).
    split; [lia|]. split; [| exact (gbo_1RB1LD_1LC1LD_0RD0LC_1RA1RD j)].
    rewrite (gso_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j E).
    exact (srun_sound tm true true chb_1RB1LD_1LC1LD_0RD0LC_1RA1RD B0_1RB1LD_1LC1LD_0RD0LC_1RA1RD BB1_1RB1LD_1LC1LD_0RD0LC_1RA1RD 8 6
             run_boot_1RB1LD_1LC1LD_0RD0LC_1RA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 20), (cden [] [] j B1_1RB1LD_1LC1LD_0RD0LC_1RA1RD).
    split; [| exact (geo_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j E)].
    rewrite (gxi_1RB1LD_1LC1LD_0RD0LC_1RA1RD j).
    exact (srun_sound tm true true che_1RB1LD_1LC1LD_0RD0LC_1RA1RD BE0_1RB1LD_1LC1LD_0RD0LC_1RA1RD B1_1RB1LD_1LC1LD_0RD0LC_1RA1RD 8 20
             run_exit_1RB1LD_1LC1LD_0RD0LC_1RA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_1RB1LD_1LC1LD_0RD0LC_1RA1RD : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_1RB1LD_1LC1LD_0RD0LC_1RA1RD : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 15.
  assert (H : match csteps tm 15 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 15 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB1LD_1LC1LD_0RD0LC_1RA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_1RB1LD_1LC1LD_0RD0LC_1RA1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_1RB1LD_1LC1LD_0RD0LC_1RA1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_1RB1LD_1LC1LD_0RD0LC_1RA1RD t p (pow2 j)).
  - exists (8 * j + 6), (cden [] [] j BB1_1RB1LD_1LC1LD_0RD0LC_1RA1RD). split;
      [| exact (gbo_1RB1LD_1LC1LD_0RD0LC_1RA1RD j)].
    rewrite (gso_1RB1LD_1LC1LD_0RD0LC_1RA1RD p j E).
    exact (srun_sound tm true true chb_1RB1LD_1LC1LD_0RD0LC_1RA1RD B0_1RB1LD_1LC1LD_0RD0LC_1RA1RD BB1_1RB1LD_1LC1LD_0RD0LC_1RA1RD 8 6
             run_boot_1RB1LD_1LC1LD_0RD0LC_1RA1RD [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_1RB1LD_1LC1LD_0RD0LC_1RA1RD xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_1RB1LD_1LC1LD_0RD0LC_1RA1RD j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB1LD_1LC1LD_0RD0LC_1RA1RD : forall t, ~ In t pins_1RB1LD_1LC1LD_0RD0LC_1RA1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB1LD_1LC1LD_0RD0LC_1RA1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1LD_0RD0LC_1RA1RD (StA, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1LD_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 5 0; SWin 6] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 2]).
    vm_compute; reflexivity.
  - (* B1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1LD_0RD0LC_1RA1RD (StB, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1LD_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 5 0; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1; SCycL 5 0; SWin 3]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1LC1LD_0RD0LC_1RA1RD
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_1RB1LD_1LC1LD_0RD0LC_1RA1RD (StD, S1)).
    intros p1 j1 E1.
    exact (firex_1RB1LD_1LC1LD_0RD0LC_1RA1RD [SRotL 1; SWin 1; SCycL 5 0; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_1RB1LD_1LC1LD_0RD0LC_1RA1RD : NeverQuasiHaltsTr tmm_1RB1LD_1LC1LD_0RD0LC_1RA1RD.
Proof.
  apply (glue_neverqhtr tmm_1RB1LD_1LC1LD_0RD0LC_1RA1RD pins_1RB1LD_1LC1LD_0RD0LC_1RA1RD Cc 1).
